package blockbranch.realistic;
import java.nio.file.*;import java.util.*;import java.lang.management.*;import net.fabricmc.fabric.api.event.lifecycle.v1.*;import net.minecraft.server.level.*;import net.minecraft.world.item.*;
public final class CoastalMatchedProbe {
 public static volatile String phase="startup";public static volatile Throwable failure;public static volatile boolean done,ready;public static volatile double tx,tz;public static volatile int mapId=-1;private static ServerPlayer player;private static long tick,start,stable,columns,begin;private static final List<Object> rows=new ArrayList<>();private static final List<Object> loads=new ArrayList<>();private static long wall,cpu,gc;private static int count;private static long maxTick;private static String config;
 static Path dir(){return Path.of(System.getProperty("blockbranch.coastalMatchedDir"));}
 static long cpu(){return ((com.sun.management.OperatingSystemMXBean)ManagementFactory.getOperatingSystemMXBean()).getProcessCpuTime();}static long gc(){return ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(b->Math.max(0,b.getCollectionTime())).sum();}
 static void mark(String next)throws Exception{long now=System.nanoTime();if(!phase.equals("startup"))rows.add(Map.of("phase",phase,"wallNanos",now-wall,"cpuNanos",cpu()-cpu,"gcMillis",gc()-gc,"ticks",tick-start,"maxTickNanos",maxTick,"loads",count,"heapUsed",ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed(),"scheduler",ProgressiveMapDrawing.audit(player.level().getServer())));if(CoastalGenerationTrace.ON&&!phase.equals("startup"))CoastalGenerationTrace.memory(phase);phase=next;wall=System.nanoTime();cpu=cpu();gc=gc();start=tick;stable=0;count=0;maxTick=0;Files.writeString(dir().resolve("phase.txt"),phase);}
 static void pose(ServerLevel level,double x,double z){tx=x;tz=z;ready=false;level.getServer().getCommands().performPrefixedCommand(level.getServer().createCommandSourceStack(),"tp "+player.getName().getString()+" "+x+" 100 "+z+" -90 35");player.getAbilities().flying=true;player.onUpdateAbilities();}
 static boolean view(ServerLevel l){if(CoastalGenerationTrace.ON){var p=player.chunkPosition();for(int z=p.z()-8;z<=p.z()+8;z++)for(int x=p.x()-8;x<=p.x()+8;x++)if(!l.getChunkSource().hasChunk(x,z))return false;return ready&&CoastalGenerationTrace.drained();}var p=player.chunkPosition();for(int z=p.z()-7;z<=p.z()+7;z++)for(int x=p.x()-7;x<=p.x()+7;x++)if(ChunkTrackingView.isInViewDistance(p.x(),p.z(),6,x,z)&&!l.getChunkSource().hasChunk(x,z))return false;return ready;}
 public static void register(){
 if(CoastalGenerationTrace.ON)ServerLifecycleEvents.SERVER_STARTED.register(s->{s.getPlayerList().setViewDistance(6);s.getPlayerList().setSimulationDistance(5);});
 ServerChunkEvents.CHUNK_LOAD.register((l,c,n)->{if(l.dimension()==net.minecraft.world.level.Level.OVERWORLD){count++;loads.add(Map.of("phase",phase,"x",c.getPos().x(),"z",c.getPos().z(),"new",n));}});
 ServerTickEvents.START_SERVER_TICK.register(s->begin=System.nanoTime());
 ServerTickEvents.END_SERVER_TICK.register(s->{if(s.isDedicatedServer()||done)return;try{tick++;if(s.getPlayerList().getPlayers().isEmpty())return;var l=s.overworld();if(player==null){player=s.getPlayerList().getPlayers().getFirst();s.getPlayerList().setViewDistance(6);s.getPlayerList().setSimulationDistance(5);s.getCommands().performPrefixedCommand(s.createCommandSourceStack(),"gamemode creative "+player.getName().getString());var ops=net.minecraft.resources.RegistryOps.create(com.mojang.serialization.JsonOps.INSTANCE,l.registryAccess());config=RealisticGenerator.CODEC.codec().encodeStart(ops,(RealisticGenerator)l.getChunkSource().getGenerator()).getOrThrow().toString();tx=player.getX();tz=player.getZ();mark("spawn-settle");return;}maxTick=Math.max(maxTick,System.nanoTime()-begin);
 if(phase.equals("map")){if(ProgressiveMapDrawing.audit(s)[0]-columns>=16){player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,ItemStack.EMPTY);mark("finish");}return;}
 if(view(l))stable++;else stable=0;
 if(CoastalGenerationTrace.ON&&tick%200==0)Files.writeString(dir().resolve("progress.json"),new com.google.gson.Gson().toJson(Map.of("phase",phase,"stable",stable,"trace",CoastalGenerationTrace.progress())));if(stable<100)return;
 switch(phase){case "spawn-settle"-> {mark("wreck-load");pose(l,-1319045.5,458339.5);}case "wreck-load"->{mark("edge-load");pose(l,-1319233.5,458304.5);}case "edge-load"->{mark("map-create");var map=MapItem.create(l,-1319360,458304,(byte)1,true,true);mapId=map.get(net.minecraft.core.component.DataComponents.MAP_ID).id();var data=MapItem.getSavedData(map,l);WellInteraction.require(java.util.Arrays.equals(data.colors,new byte[16384]),"Identical controlled blank native map input");columns=ProgressiveMapDrawing.audit(s)[0];mark("map");player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,map);}case "finish"->{var data=MapItem.getSavedData(new net.minecraft.world.level.saveddata.maps.MapId(mapId),l);Files.writeString(dir().resolve("results.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(Map.of("phases",rows,"loads",loads,"configuration",config,"pixels",java.util.Base64.getEncoder().encodeToString(data.colors),"java",System.getProperty("java.version"),"processors",Runtime.getRuntime().availableProcessors(),"trace",CoastalGenerationTrace.snapshot())));done=true;Files.writeString(dir().resolve("result.txt"),"PASS");}default->{}}
 }catch(Throwable t){failure=t;done=true;try{Files.writeString(dir().resolve("result.txt"),"FAIL "+t);}catch(Exception e){}}});}
}
